from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        def count_subarrays(start, end, k):
            if start == end:
                return 1
            if start > end:
                return 0

            mid = start + (end - start) // 2
            left = mid
            right = mid + 1

            # Count subarrays where the middle element is the minimum
            count = count_subarrays(start, left - 1, k)

            # Count subarrays where the middle element is not the minimum
            for i in range(left + 1, end + 1):
                diff = prefix_sum[i] - prefix_sum[mid]
                if diff <= k:
                    count += count_subarrays(mid + 1, i - 1, k - diff)

            return count

        return n * (n + 1) // 2 - count_subarrays(0, n - 1, k)
```

