class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Count the occurrence of each integer
        count = {}
        for num in nums:
            if num not in count:
                count[num] = 1
            else:
                count[num] += 1

        # Initialize the maximum almost missing integer
        max_almost_missing = -1

        # Iterate over the array
        for i in range(len(nums)):
            # If the number of occurrences is 1, update max_almost_missing
            if count[nums[i]] == 1:
                max_almost_missing = nums[i]
                count[nums[i]] -= 1
            # If the number of occurrences is greater than 1, decrement it
            else:
                count[nums[i]] -= 1

            # If the window size is equal to k, slide the window
            if i >= k - 1:
                # Remove the number that is out of the window
                count[nums[i - k + 1]] += 1

        # Return the maximum almost missing integer
        return max_almost_missing
